   149		}
   150		sortSearchCandidates(candidates)
   151	
   152		document := searchCandidateResults(selectSearchCandidates(candidates, q, 12, 3, false))
   153		section := searchCandidateResults(selectSearchCandidates(candidates, q, 12, 3, true))
   154		if len(document) != len(section) {
   155			t.Fatalf("code selection changed size: %d -> %d", len(document), len(section))
   156		}
   157		for index := range document {
   158			if !reflect.DeepEqual(document[index], section[index]) {
   159				t.Fatalf("code result %d changed:\n want %#v\n  got %#v", index, document[index], section[index])
   160			}
   161		}
   162	}
