   164	// Passages are planned per selected unit over the whole document, so without deduplication the
   165	// same region is attached to every selected section of that document and the payload shows one
   166	// region several times over.
   167	func TestSearchRepositoryReturnsEveryProseRegionOnce(t *testing.T) {
   168		repo := t.TempDir()
   169		for index := 0; index < 5; index++ {
   170			var body strings.Builder
   171			body.WriteString("# Session\n\n")
   172			for turn := 0; turn < 9; turn++ {
   173				fmt.Fprintf(&body, "## turn %d: amber lantern orchard ledger vessel ridge marker%d\n\n", turn, turn)
   174			}
   175			write(t, repo, fmt.Sprintf("sessions/session-%02d.md", index), body.String())
   176		}
   177	
   178		response, err := SearchRepository(
   179			t.Context(), repo, "test", "amber lantern orchard ledger vessel", SearchOptions{
   180				Worktree: true, Profile: ProfileSyntaxOnly, TopK: 20,
   181				MaxIndexedFiles: 32, MaxContextBytes: 400000,
   182			},
   183		)
   184		if err != nil {
   185			t.Fatal(err)
   186		}
   187		if err := response.Validate(); err != nil {
   188			t.Fatalf("invalid response: %v", err)
   189		}
   190		type span struct {
   191			path       string
   192			start, end int
   193		}
   194		seen := map[span]int{}
   195		total := 0
   196		for _, result := range response.Results {
   197			seen[span{result.FilePath, result.SnippetStartLine, result.SnippetEndLine}]++
   198			total++
   199			for _, passage := range result.Passages {
   200				seen[span{result.FilePath, passage.StartLine, passage.EndLine}]++
   201				total++
   202			}
   203		}
   204		if len(seen) != total {
   205			for key, count := range seen {
   206				if count > 1 {
   207					t.Errorf("region %v returned %d times", key, count)
   208				}
   209			}
   210			t.Fatalf("%d regions returned over %d distinct spans", total, len(seen))
   211		}
   212	}
