    20	
    21	## Orchard
    22	
    23	second note
    24	
    25	## Ledger
    26	
    27	third note
    28	
    29	## Braided
    30	
    31	fourth note
    32	
    33	## Lantern
    34	
    35	closing note
    36	`)
    37		for index := 0; index < 17; index++ {
    38			write(t, repo, fmt.Sprintf("sessions/distractor-%02d.md", index), fmt.Sprintf(
    39				"# Amber orchard ledger braided marker%d ridge%d vessel%d\n\nUnrelated archive.\n",
    40				index, index, index,
    41			))
    42		}
    43	
    44		response, err := SearchRepository(
    45			t.Context(), repo, "test", "amber orchard ledger braided lantern", SearchOptions{
    46				Worktree:        true,
    47				Profile:         ProfileSyntaxOnly,
    48				TopK:            10,
    49				MaxIndexedFiles: 32,
    50			},
    51		)
    52		if err != nil {
    53			t.Fatal(err)
    54		}
    55		assertSearchResultGolden(t, response.Results, "6efd6795a9f0d1f2969f167676c81e22f6cd9aaa74ec7270c6d5f98e10ec9878")
    56		wantHead := []string{
    57			"sessions/distractor-00.md",
    58			"sessions/distractor-01.md",
    59			"sessions/distractor-02.md",
    60			"sessions/distractor-03.md",
    61			"sessions/distractor-04.md",
    62		}
    63		for index, path := range wantHead {
    64			if response.Results[index].FilePath != path {
    65				t.Fatalf("preserved head[%d] = %q, want %q", index, response.Results[index].FilePath, path)
    66			}
    67		}
    68		for _, result := range response.Results {
    69			if result.FilePath != "sessions/focus.md" {
    70				continue
    71			}
    72			if result.Rank != 6 {
    73				t.Fatalf("distributed session rank = %d, want first fair tail slot 6", result.Rank)
