    91	
    92	## Ledgers
    93	
    94	## Lanterns
    95	
    96	## Vessels
    97	`)
    98		for index := 0; index < 11; index++ {
    99			write(t, repo, fmt.Sprintf("sessions/distractor-%02d.md", index), fmt.Sprintf(
   100				"# Amber orchard ledger lantern marker%d ridge%d route%d\n",
   101				index, index, index,
   102			))
   103		}
   104	
   105		response, err := SearchRepository(
   106			t.Context(), repo, "test", "amber orchard ledger lantern vessel", SearchOptions{
   107				Worktree:        true,
   108				Profile:         ProfileSyntaxOnly,
   109				TopK:            10,
   110				MaxIndexedFiles: 32,
   111			},
   112		)
   113		if err != nil {
   114			t.Fatal(err)
   115		}
   116		// The admitted region is `## Vessels`, the section that carries the one query term no other
   117		// document matches, rather than the document's globally best `# Ambers` heading: with the
   118		// section as the ranked unit, the region that earned the slot is the region returned. Same
   119		// rank, same score, same five regions.
   120		assertSearchResultGolden(t, response.Results, "72795b2d906d1b141b4b040d82d8ef4e7d69d1a652bc16e72cbdb804524be5fc")
   121		for _, result := range response.Results {
   122			if result.FilePath == "sessions/focus.md" &&
   123				containsString(result.Signals, "retrieval_mode=prose-parent") {
   124				if result.StartLine != 9 {
   125					t.Fatalf("admitted region start = %d, want the `## Vessels` section at 9", result.StartLine)
   126				}
   127				if result.Rank != 6 {
   128					t.Fatalf("plural session rank = %d, want first fair tail slot 6", result.Rank)
   129				}
   130				return
   131			}
   132		}
   133		t.Fatalf("safe plural session missing from top 10: %#v", response.Results)
   134	}
